b=Book('14.3',[1007,1008,1009,1010,1011]);old=json.loads((ROOT/'s14-3.json').read_text());b.E={e['number']:e for e in old['exercises'] if e['number']in range(9,17)}
x,y,z,t,u,v,r,q,p,a,c,d,ss=s.symbols('x y z t u v r q p a c d s',real=True);aa,bb,gg,dd=s.symbols('alpha beta gamma delta',real=True);theta=s.symbols('theta',real=True)
def tex(e):return s.latex(s.factor(e))
def add(n,title,st,steps,ans,parts=[],check=None):b.add(n,1007 if n<=7 else 1008 if n<=68 else 1009 if n<=79 else 1010 if n<=92 else 1011,title,st,steps,ans,parts,check=check)
def calc(n,f,variables,name='f',orders=None,title=None):
 F=tex(f);wanted=[(i,)for i in variables]if orders is None else orders;derivs=[];steps=[('선택한 변수 이외에는 모두 상수로 두고 곱·몫·연쇄법칙을 적용한다.','Hold every variable except the selected one constant and apply the product, quotient, and chain rules.')]
 for order in wanted:
  res=s.diff(f,*order);label=name+'_{'+' '.join(s.latex(k)for k in order)+'}';derivs.append(label+'='+tex(res))
  if len(order)>1:steps+=fs(name+'_{'+' '.join(s.latex(k)for k in order[:-1])+'}='+tex(s.diff(f,*order[:-1])))
  steps+=fs(label+'='+tex(res))
 request='1계 편도함수를 모두 구하라.'if orders is None else'지정한 편도함수를 구하라.';en='Find all first partial derivatives.'if orders is None else'Find the indicated partial derivatives.'
 spec=''if orders is None else r'\('+',\ '.join(name+'_{'+' '.join(s.latex(k)for k in o)+'}'for o in wanted)+r'\).'
 add(n,title or('편도함수 계산','Computing partial derivatives'),(request+r'\('+name+'='+F+r'\).'+spec,en+r'\('+name+'='+F+r'\).'+spec),steps,same(r'\['+r',\qquad '.join(derivs)+r'.\]'),check=('독립적인 기호미분으로 각 결과를 대조했다. 식의 분모·로그·제곱근이 허용되는 미분 가능 영역에서의 공식이다.','Each result was cross-checked by symbolic differentiation. Formulas apply on the differentiable domain allowed by denominators, logarithms, and roots.'))
add(1,('체감온도의 편미분','Partial derivatives of heat index'),('교재 표에서 '+r'\(f_T(92,60),\ f_H(92,60)\)'+'을 근사하고 해석하라. 필요한 값은 f(90,60)=100, f(94,60)=111, f(92,55)=103, f(92,65)=108이다(T와 I는°F, H는%).','Estimate and interpret '+r'\(f_T(92,60),\ f_H(92,60)\)'+' using f(90,60)=100, f(94,60)=111, f(92,55)=103, f(92,65)=108 from the textbook table (T and I in°F; H in%).'),fs(r'f_T(92,60)\approx\frac{111-100}{94-90}=2.75',r'f_H(92,60)\approx\frac{108-103}{65-55}=0.5')+[('습도를60%로 고정하면 실제온도1°F 상승당 체감온도 약2.75°F 증가, 온도를92°F로 고정하면 습도1퍼센트포인트 상승당 약0.5°F 증가이다.','At60% humidity, a1°F rise in temperature increases heat index by about2.75°F. At92°F, a1-percentage-point rise in humidity increases it by about0.5°F.')],same(r'\[f_T\approx2.75\ \mathrm{^{\circ}F/^{\circ}F},\qquad f_H\approx0.5\ \mathrm{^{\circ}F/percentage\ point}.\]'))
add(2,('파고의 편미분','Partial derivatives of wave height'),('파고 h=f(v,t)(피트), 풍속 v(노트), 지속시간 t(시간)에 대해 (a) 두 편미분을 해석하고 (b) (40,15)에서 추정하며 (c) t→∞일 때 h_t의 경향을 구하라. 표에서 f(30,15)=16, f(50,15)=36, f(40,10)=21, f(40,20)=28이며 풍속40에서 t=30,40,50의 값은31,33,33이다.','For wave height h=f(v,t) in feet, speed v in knots and duration t in hours, (a) interpret the partials; (b) estimate at (40,15); (c) infer h_t as t→∞. Table entries are f(30,15)=16, f(50,15)=36, f(40,10)=21, f(40,20)=28; at speed40 the values for t=30,40,50 are31,33,33.'),[('(a) h_v는 시간을 고정한 풍속당 파고 변화, h_t는 풍속을 고정한 시간당 파고 변화이다.','(a) h_v measures height change per knot at fixed duration; h_t measures height change per hour at fixed wind speed.')]+fs(r'(b)\ f_v(40,15)\approx(36-16)/20=1,\quad f_t(40,15)\approx(28-21)/10=0.7')+[('(c) 장시간 후 높이가 포화되는 표의 경향에 따라 변화율은0으로 접근한다고 예상한다. 유한한 표만으로 증명한 극한은 아니다.','(c) The table suggests saturation and hence a rate tending to0; a finite table alone does not prove that limit.')],same(r'\[(b)\ f_v\approx1\ \mathrm{ft/knot},\quad f_t\approx0.7\ \mathrm{ft/h};\qquad(c)\ h_t\to0\ \text{(suggested)}.\]'),['a','b','c'])
add(3,('온도장의 방향과 시간','Spatial and temporal temperature changes'),('T=f(x,y,t)에서 x는 서경의 도수, y는 북위의 도수, t는1월1일부터 경과시간이다. (a) 세 편미분을 해석하라. (b) 호놀룰루(158,21), t=9에서 서·남쪽은 따뜻하고 동·북쪽은 차며 따뜻한 공기가 북동쪽으로 이동할 때 세 편미분의 부호를 예상하라.','For T=f(x,y,t), x measures degrees west, y degrees north, and t hours since January1, (a) interpret the three partials. (b) At Honolulu(158,21), t=9, warmer air lies west and south, cooler air east and north, and warm air moves northeast. Predict the signs.'),[('(a) 다른 두 변수를 고정할 때 각각 경도·위도·시간당 온도의 변화율이다.','(a) They are changes per unit longitude, latitude, and time, holding the other two variables fixed.'),('(b) 서경x가 증가하면 따뜻한 서쪽으로 가므로 양수, 북위y가 증가하면 찬 북쪽이므로 음수, 따뜻한 공기가 도착하므로 시간 미분은 양수이다.','(b) Increasing west longitude moves into warmer air, increasing latitude into cooler air, and incoming warm air raises temperature over time.')],same(r'\[f_x(158,21,9)>0,\quad f_y(158,21,9)<0,\quad f_t(158,21,9)>0.\]'),['a','b'])
for n,pt,sx in[(4,'(1,2)','>'),(5,'(-1,2)','<')]:
 add(n,('그래프에서 기울기 부호','Signs of slopes from a graph'),('교재 안장 모양 그래프에서 (a) '+r'\(f_x'+pt+r'\)'+'와 (b) '+r'\(f_y'+pt+r'\)'+'의 부호를 정하라.','For the source saddle-shaped graph, determine signs of (a) '+r'\(f_x'+pt+r'\)'+' and (b) '+r'\(f_y'+pt+r'\)'+'.'),[('y=2 단면은 x=0 부근에서 낮고 양옆으로 높아지는 곡선이다.','The y=2 section has a trough near x=0 and rises on both sides.'),('두 지정된 점에서 양의 y방향으로 움직이면 높이가 내려간다.','At both specified points, moving in positive y decreases the height.')],same(r'\[(a)\ f_x'+pt+sx+r'0;\qquad(b)\ f_y'+pt+r'<0.\]'),['a','b'])
add(6,('등고선으로 편미분 추정','Estimating partials from contours'),('교재 등고선에서 '+r'\(f_x(2,1),\ f_y(2,1)\)'+'을 추정하라. 해당 근방에서 오른쪽으로 등고선값이 증가하고 위쪽으로 감소하며 인접 등고선의 값 차이는2이다.','Estimate '+r'\(f_x(2,1),\ f_y(2,1)\)'+' from the source contour map. Nearby, values increase rightward and decrease upward, with increment2 between adjacent contours.'),[('수평선 y=1에서 값이2 증가하는 데 필요한 거리가 약0.5이므로 변화율은 약4이다.','Along y=1, an increase of2 takes about0.5 horizontal unit, giving a slope near4.'),('수직선 x=2에서 위쪽 약1단위 이동에 값이약2 줄어들므로 변화율은 약-2이다.','Along x=2, a rise of about1 vertical unit lowers f by about2, giving a slope near-2.')],same(r'\[f_x(2,1)\approx4,\qquad f_y(2,1)\approx-2.\]'),check=('그림에서 읽는 근사이므로 작은 눈금 판독 차이에 따른 오차가 허용된다.','These are graphical estimates, allowing small differences from reading the grid.'))
for n,F,pt,dx,dy,P in[(7,r'16-4x^2-y^2',r'(1,2)',r'-8',r'-4',r'(1,2,8)'),(8,r'\sqrt{4-x^2-4y^2}',r'(1,0)',r'-1/\sqrt3','0',r'(1,0,\sqrt3)')]:
 deriv=(r'f_x=-8x,\quad f_y=-2y')if n==7 else(r'f_x=-x/\sqrt{4-x^2-4y^2},\quad f_y=-4y/\sqrt{4-x^2-4y^2}')
 add(n,('편미분과 단면 접선','Partial derivatives and trace tangents'),('함수 '+r'\(f='+F+r'\)'+'의 '+r'\(f_x'+pt+',\ f_y'+pt+r'\)'+'를 구하고 접선 기울기로 해석하여 그려라.','For '+r'\(f='+F+r'\)'+' find '+r'\(f_x'+pt+',\ f_y'+pt+r'\)'+' and illustrate their meanings as tangent slopes.'),fs(deriv,r'P='+P)+[('x편미분은 y를 고정한 수직단면의 기울기이고, y편미분은 x를 고정한 단면의 기울기이다.','The x-partial is the tangent slope in the vertical trace with y fixed; the y-partial uses the trace with x fixed.')],same(r'\[f_x'+pt+'='+dx+r',\qquad f_y'+pt+'='+dy+r'.\]'))
