first=[(17,y*(x+x*x*y)**5,[x,y],'g'),(18,x/(x+y)**2,[x,y],'f'),(19,(a*x+s.Symbol('b',real=True)*y)/(c*x+d*y),[x,y],'f'),(20,s.exp(v)/(u+v*v),[u,v],'w'),(21,(u*u*v-v**3)**5,[u,v],'g'),(22,s.sin(r*s.cos(theta)),[r,theta],'u'),(23,s.atan(p*q*q),[p,q],'R'),(24,x**y,[x,y],'f'),(27,x**3*y*z*z+2*y*z,[x,y,z],'f'),(28,x*y*y*s.exp(-x*z),[x,y,z],'f'),(29,s.log(x+2*y+3*z),[x,y,z],'w'),(30,y*s.tan(x+2*z),[x,y,z],'w'),(31,s.sqrt(t**4+u*u*s.cos(v)),[t,u,v],'p'),(32,x**(y/z),[x,y,z],'u'),(33,x*x*y*s.cos(z/t),[x,y,z,t],'h'),(34,(aa*x+bb*y*y)/(gg*z+dd*t*t),[x,y,z,t],r'\phi')]
for n,F,vs,name in first:calc(n,F,vs,name)
for n in[24,32]:b.E[n]['steps']['ko'].insert(0,'실수 거듭제곱의 일반적인 미분 영역 x>0에서 계산한다.');b.E[n]['steps']['en'].insert(0,'Work on x>0, the usual differentiable domain for a general real power.')
for n,F,deriv in[(25,r'F(x,y)=\int_y^x\cos(e^t)\,dt',r'F_x=\cos(e^x),\quad F_y=-\cos(e^y)'),(26,r'F(\alpha,\beta)=\int_\alpha^\beta\sqrt{t^3+1}\,dt',r'F_\alpha=-\sqrt{\alpha^3+1},\quad F_\beta=\sqrt{\beta^3+1}')]:
 add(n,('가변 적분구간 미분','Differentiating variable endpoints'),('1계 편도함수를 구하라. '+r'\('+F+r'\).','Find the first partials of '+r'\('+F+r'\).'),[('적분 상한의 미분은 적분함수값, 하한의 미분은 그 음수이다.','The upper-endpoint derivative is the integrand value; the lower-endpoint derivative is its negative.')]+fs(deriv),same(r'\['+deriv+r'.\]'))
add(35,('n변수 노름의 편미분','Partials of an n-variable norm'),('1계 편도함수를 구하라. '+r'\(u=\sqrt{x_1^2+\cdots+x_n^2}\).','Find all first partial derivatives of '+r'\(u=\sqrt{x_1^2+\cdots+x_n^2}\).'),fs(r'\frac{\partial u}{\partial x_i}=\frac12(\sum_jx_j^2)^{-1/2}(2x_i)')+[('원점에서는 해당 좌표축을 따라 절댓값 함수가 되므로 두쪽 편미분이 존재하지 않는다.','At the origin each coordinate restriction is an absolute-value function, so the two-sided partial does not exist.')],same(r'\[u_{x_i}=\frac{x_i}{\sqrt{\sum_jx_j^2}}\quad(\mathbf x\ne0);\qquad u_{x_i}(0)\text{ does not exist}.\]'))
add(36,('n변수 합성함수의 편미분','Partials of an n-variable composition'),('모든1계 편도함수를 구하라. '+r'\(u=\sin(x_1+2x_2+\cdots+nx_n)\).','Find all first partials of '+r'\(u=\sin(x_1+2x_2+\cdots+nx_n)\).'),fs(r'L=\sum_{j=1}^njx_j,\quad L_{x_i}=i',r'u_{x_i}=\cos L\cdot i'),same(r'\[u_{x_i}=i\cos\left(\sum_{j=1}^njx_j\right),\quad i=1,\ldots,n.\]'))
add(37,('지정점 편미분','Partial at a specified point'),('계산하라. '+r'\(R(s,t)=te^{s/t},\quad R_t(0,1)\).','Evaluate '+r'\(R(s,t)=te^{s/t},\quad R_t(0,1)\).'),fs(r'R_t=e^{s/t}+te^{s/t}(-s/t^2)=e^{s/t}(1-s/t)'),same(r'\[R_t(0,1)=1.\]'))
add(38,('역삼각함수 편미분','Partial of an inverse trigonometric function'),('계산하라. '+r'\(f(x,y)=y\arcsin(xy),\quad f_y(1,1/2)\).','Evaluate '+r'\(f(x,y)=y\arcsin(xy),\quad f_y(1,1/2)\).'),fs(r'f_y=\arcsin(xy)+\frac{xy}{\sqrt{1-x^2y^2}}'),same(r'\[f_y(1,1/2)=\pi/6+1/\sqrt3.\]'))
add(39,('로그 정의역 확인','Checking a logarithm domain'),('원문이 제시한 값을 검토하라. '+r'\(f=\ln\frac{1-\sqrt{x^2+y^2+z^2}}{1+\sqrt{x^2+y^2+z^2}},\quad f_y(1,2,2)\).','Examine the requested value in the printed exercise: '+r'\(f=\ln\frac{1-\sqrt{x^2+y^2+z^2}}{1+\sqrt{x^2+y^2+z^2}},\quad f_y(1,2,2)\).'),fs(r'r=\sqrt{x^2+y^2+z^2}=3,\quad(1-r)/(1+r)=-1/2')+[('원문의 실수 로그는 이 점에서 정의되지 않으므로 실수 편미분도 없다. 부록의1/6은 로그인수의 절댓값을 취한 수정식에 해당한다.','The printed real logarithm is undefined here, so its real partial derivative does not exist. The appendix value1/6 corresponds to correcting the logarithm with an absolute value.')]+fs(r'\widetilde f=\ln\left|\frac{1-r}{1+r}\right|,\quad\widetilde f_y=-\frac{2y}{r(1-r^2)},\quad\widetilde f_y(1,2,2)=1/6'),('원문 그대로의 실수 편미분은 미정의. 로그절댓값 수정 시1/6.','The printed real partial is undefined. With an absolute-value logarithm correction, it is1/6.'),check=('PDF1045 이미지와 원문 조건을 보존하여 정의역 오류와 형식적 계산을 분리했다.','The PDF1045 image and original conditions are preserved; the domain error is distinguished from the formal computation.'))
add(40,('지수에 대한 편미분','Differentiating a variable exponent'),('계산하라. '+r'\(f=x^{yz},\quad f_z(e,1,0)\).','Evaluate '+r'\(f=x^{yz},\quad f_z(e,1,0)\).'),fs(r'f=e^{yz\ln x},\quad f_z=y\ln x\,x^{yz}'),same(r'\[f_z(e,1,0)=1.\]'))
for n,F in[(41,x*x+2*y*y+3*z*z-1),(42,x*x-y*y+z*z-2*z-4),(43,s.exp(z)-x*y*z),(44,y*z+x*s.log(y)-z*z)]:
 zx=-s.diff(F,x)/s.diff(F,z);zy=-s.diff(F,y)/s.diff(F,z)
 add(n,('음함수 편미분','Implicit partial differentiation'),('음함수 미분으로 '+r'\(z_x,z_y\)'+'를 구하라. '+r'\('+tex(F)+'=0'+r'\).','Use implicit differentiation to find '+r'\(z_x,z_y\)'+' from '+r'\('+tex(F)+'=0'+r'\).'),fs(r'F_x+F_zz_x=0,\quad F_y+F_zz_y=0',r'F_z='+tex(s.diff(F,z))),same(r'\[z_x='+tex(zx)+r',\qquad z_y='+tex(zy)+r'.\]'),check=('z를 x,y의 미분가능함수로 나타낼 수 있고 F_z≠0인 점에서 적용한다.','These formulas apply where z is a differentiable function of x,y and F_z≠0.'))
add(45,('일반 함수의 합과 합성','Sums and compositions of general functions'),('각 경우 '+r'\(z_x,z_y\)'+'를 구하라: (a) '+r'\(z=f(x)+g(y)\)'+'; (b) '+r'\(z=f(x+y)\)'+'.','Find '+r'\(z_x,z_y\)'+' for (a) '+r'\(z=f(x)+g(y)\)'+' and (b) '+r'\(z=f(x+y)\)'+'.'),[('(a) 다른 변수만 포함한 항은 상수이다. (b) 내부함수 x+y의 각 편미분은1이다.','(a) A term involving only the other variable is constant. (b) Each partial of the inner function x+y is1.')]+fs(r'(a)\ z_x=f\prime(x),\ z_y=g\prime(y);\qquad(b)\ z_x=z_y=f\prime(x+y)'),same(r'\[(a)\ (f\prime(x),g\prime(y));\quad(b)\ (f\prime(x+y),f\prime(x+y)).\]'),['a','b'])
add(46,('곱·곱합성·몫합성','Products and composed products or quotients'),('각 경우 '+r'\(z_x,z_y\)'+'를 구하라: (a) '+r'\(z=f(x)g(y)\)'+'; (b) '+r'\(z=f(xy)\)'+'; (c) '+r'\(z=f(x/y)\)'+'.','Find '+r'\(z_x,z_y\)'+' for (a) '+r'\(z=f(x)g(y)\)'+'; (b) '+r'\(z=f(xy)\)'+'; (c) '+r'\(z=f(x/y)\)'+'.'),fs(r'(a)\ z_x=f\prime(x)g(y),\quad z_y=f(x)g\prime(y)',r'(b)\ z_x=yf\prime(xy),\quad z_y=xf\prime(xy)',r'(c)\ z_x=f\prime(x/y)/y,\quad z_y=-xf\prime(x/y)/y^2'),same(r'\[(a)\ (f\prime(x)g(y),f(x)g\prime(y));\quad(b)\ (yf\prime(xy),xf\prime(xy));\quad(c)\ (f\prime(x/y)/y,-xf\prime(x/y)/y^2).\]'),['a','b','c'])
