for n,F in[(53,x**4*y**3-y**4),(54,s.exp(x*y)*s.sin(y)),(55,s.cos(x*x*y)),(56,s.log(x+2*y))]:calc(n,F,[x,y],'u',[(x,y),(y,x)],('혼합편미분의 교환','Equality of mixed partials'))
for n,F,orders,name in[(57,x**4*y*y-x**3*y,[(x,x,x),(x,y,x)],'f'),(58,s.sin(2*x+5*y),[(y,x,y)],'f'),(59,s.exp(x*y*z*z),[(x,y,z)],'f'),(60,s.exp(r)*s.sin(ss*t),[(r,ss,t)],'g'),(61,s.sqrt(u+v*v),[(u,u,v)],'W'),(62,s.log(r+ss*ss+t**3),[(r,ss,t)],'V'),(63,x/(y+2*z),[(x,y,z),(y,x,x)],'w')]:calc(n,F,[],name,orders)
add(64,('여섯 번의 편미분','A sixth-order mixed partial'),('지정한 편미분을 구하라. '+r'\(u=x^ay^bz^c,\quad\partial^6u/(\partial x\partial y^2\partial z^3)\).','Find '+r'\(u=x^ay^bz^c,\quad\partial^6u/(\partial x\partial y^2\partial z^3)\).'),[('x인자를 한 번, y인자를 두 번, z인자를 세 번 미분한다. 각 거듭제곱의 지수가 차례로 내려간다.','Differentiate the x-factor once, the y-factor twice, and the z-factor three times, lowering each exponent in turn.')]+fs(r'(x^a)\prime=ax^{a-1},\quad(y^b)\prime\prime=b(b-1)y^{b-2},\quad(z^c)\prime\prime\prime=c(c-1)(c-2)z^{c-3}'),same(r'\[ab(b-1)c(c-1)(c-2)x^{a-1}y^{b-2}z^{c-3}.\]'))
add(65,('정의로 다항식 편미분','Polynomial partials from the definition'),('극한 정의를 사용하여 두 편미분을 구하라. '+r'\(f=xy^2-x^3y\).','Use the limit definition to find both partials of '+r'\(f=xy^2-x^3y\).'),fs(r'\frac{f(x+h,y)-f(x,y)}h=y^2-y(3x^2+3xh+h^2)',r'\frac{f(x,y+h)-f(x,y)}h=x(2y+h)-x^3'),same(r'\[f_x=y^2-3x^2y,\qquad f_y=2xy-x^3.\]'))
add(66,('정의로 유리함수 편미분','Rational partials from the definition'),('극한 정의로 편미분을 구하라. '+r'\(f=x/(x+y^2)\).','Use the limit definition for '+r'\(f=x/(x+y^2)\).'),fs(r'\frac{f(x+h,y)-f(x,y)}h=\frac{y^2}{(x+h+y^2)(x+y^2)}',r'\frac{f(x,y+h)-f(x,y)}h=\frac{-x(2y+h)}{(x+(y+h)^2)(x+y^2)}'),same(r'\[f_x=\frac{y^2}{(x+y^2)^2},\qquad f_y=-\frac{2xy}{(x+y^2)^2}.\]'))
add(67,('미분 순서 선택','Choosing an efficient derivative order'),('편미분을 구하라. '+r'\(f=xy^2z^3+\arcsin(x\sqrt z),\quad f_{xzy}\).','Find '+r'\(f=xy^2z^3+\arcsin(x\sqrt z),\quad f_{xzy}\).'),[('미분가능한 내부 영역에서 혼합미분 순서를 바꾸어 y부터 미분하면 역삼각함수 항이 사라진다.','In the smooth interior, interchange the order and differentiate y first to remove the inverse-trigonometric term.')]+fs(r'f_y=2xyz^3,\quad f_{yx}=2yz^3,\quad f_{yxz}=6yz^2'),same(r'\[f_{xzy}=6yz^2.\]'))
add(68,('변수에 독립적인 항','Terms independent of a variable'),('편미분을 구하라. '+r'\(g=\sqrt{1+xz}+\sqrt{1-xy},\quad g_{yxz}\).','Find '+r'\(g=\sqrt{1+xz}+\sqrt{1-xy},\quad g_{yxz}\).'),[('첫 항은 y와 무관하므로 y미분에서 사라진다. 남은 항은 z와 무관하다.','The first term is independent of y and disappears upon y-differentiation. The remaining term is independent of z.'),(r'따라서 제곱근 내부가 양수인 매끄러운 영역에서 \(g_{yxz}=0\)이다.',r'Thus on the smooth region with positive radicands, \(g_{yxz}=0\).')],same(r'\[g_{yxz}=0.\]'))
